dw:transform-message.dw:set-payload:
%dw 2.0
output application/json
var input_map = {}
var output_map = {}
var skip = false
try {
  input_map = parse_hl7_message(payload)
  output_map = {}
  if (input_map.MSA) {
    var msa_segment = input_map.MSA[0]
    var msa_text_message = msa_segment['MSA-3-text_message']
    if (msa_text_message contains 'ZZZ') {
      skip = true
    }
  }
  if (!skip) {
    output_map.MSH = input_map.MSH
    output_map.MSA = input_map.MSA
    return output_map as String
  }
  return ''
} catch (error) {
  return ''
} finally {
  input_map = {}
  output_map = {}
}
